def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([2, 1]), fmt([1, 2]), fmt([3, 3, 3]), fmt([-10**9, 10**9, 0]),
             fmt([5, 4, 3, 2, 1]), fmt([1, 2, 3, 4, 5])]
    for n in (3, 5, 8, 12, 20, 40):
        for _ in range(2):
            tests.append(fmt([rng.randint(-50, 50) for _ in range(n)]))
        tests.append(fmt([rng.randint(0, 2) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(list(range(N))))
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt([rng.randint(0, 3) for _ in range(N)]))
    tests.append(fmt([42] * N))
    return tests
